  const rows=[...model.activeSales.map(g=>({g,st:'محسوبة',cls:'ok'})),...model.cancelledSales.map(g=>({g,st:`ملغاة بمرتجع ${g.matchedReturn||''}`,cls:'cancel'}))]
    .sort((a,b)=>(b.g.date?+b.g.date:0)-(a.g.date?+a.g.date:0)||invoiceNumValue(b.g.invoice)-invoiceNumValue(a.g.invoice)).slice(0,8);
