function reportPaymentDateParts(r){
  const pd=parseDate(r&&r.date?r.date:'');
  const m=String(pd).match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if(!m)return null;
  return {year:+m[1],monthIndex:(+m[2])-1,month:MONTHS[(+m[2])-1],day:+m[3],iso:`${m[1]}-${String(+m[2]).padStart(2,'0')}-${String(+m[3]).padStart(2,'0')}`};
}
