function reportPaymentVehicleIcon(v){
  const s=String(v||'');
  if(/كل/.test(s))return '🚗';
  if(/شاح|truck|لوري/i.test(s))return '🚚';
  if(/بنك|تحويل|شبك|نقد|cash|bank/i.test(s))return '💳';
  if(/جيب|jeep/i.test(s))return '🚙';
  return '🚘';
}
