function renderReportPayment(data){
  if(!reportPaymentSelectedYear) reportPaymentSelectedYear=String(defaultYear(data));
  const y=reportPaymentSelectedYearValue(data);
  let sourceBase= y==='all' ? data.slice() : byYear(data,y);

  const availableVehicles=reportPaymentUniqueVehicles(sourceBase);
  reportPaymentVehicleFilters=reportPaymentVehicleFilters.filter(v=>availableVehicles.includes(v));
  const availablePays=reportPaymentUniquePays(sourceBase);
  if(reportPaymentSelectedPay && !availablePays.includes(reportPaymentSelectedPay)) reportPaymentSelectedPay='';

  let source=sourceBase.slice();
  if(reportPaymentVehicleFilters.length) source=source.filter(r=>reportPaymentVehicleFilters.includes(String(r.van||'غير محدد').trim()));
  if(reportPaymentSelectedPay) source=source.filter(r=>String(r.pay||'غير محدد').trim()===reportPaymentSelectedPay);
  if(reportPaymentSelectedMonth) source=source.filter(r=>normalizeMonth(r.month,r.date)===reportPaymentSelectedMonth);
  if(reportPaymentSelectedDay) source=source.filter(r=>{const p=reportPaymentDateParts(r);return p && String(p.day)===String(reportPaymentSelectedDay);});

  let pays=[...new Set(source.map(r=>String(r.pay||'غير محدد').trim()))].filter(Boolean);
  if(!pays.length) pays=availablePays.length?availablePays:['غير محدد'];
  let total=source.reduce((s,r)=>s+parseNum(r.totalInc),0);
  let html=buildReportPaymentControls(data,y,sourceBase);
  html+=reportKpis([['إجمالي المدفوعات',money(total)],['أعلى طريقة دفع',(Object.entries(groupSum(source,'pay')).sort((a,b)=>b[1]-a[1])[0]||['-',0])[0]],['السنة المعروضة',y==='all'?'كل السنوات':y],['عدد الطرق',pays.length],['نوع العرض',reportPaymentSelectedMonth?(reportPaymentSelectedDay?'يومي':'أيام الشهر'):'قيم فعلية']]);
  html+=`<div class="report-full"><div class="card"><div class="chart-head payment-chart-title-row"><div><b>${reportPaymentSelectedMonth?'توزيع طرق الدفع داخل شهر '+MAR[reportPaymentSelectedMonth]:'توزيع طرق الدفع شهرياً'} (القيمة الفعلية بالريال السعودي)</b></div></div>${source.length?`<div class="chart pay"><canvas id="reportPaymentMonthly"></canvas></div>`:`<div class="payment-no-data">لا توجد بيانات مطابقة للفلاتر الحالية.</div>`}</div></div>`;
  $('reportDynamic').innerHTML=html;
  bindReportPaymentControls();
  if(!source.length)return;

  const colors=[css('--green'),css('--purple'),css('--blue'),css('--orange'),css('--pink'),css('--cyan')];
  let labels=[], datasets=[];
  if(reportPaymentSelectedMonth){
    const viewYear=(y==='all'?defaultYear(data):y), mi=MONTHS.indexOf(reportPaymentSelectedMonth), daysInMonth=new Date(viewYear,mi+1,0).getDate();
    labels=Array.from({length:daysInMonth},(_,i)=>String(i+1));
    datasets=pays.map((p,i)=>({label:p,data:labels.map(day=>source.filter(r=>{const dp=reportPaymentDateParts(r);return dp && String(dp.day)===String(day) && dp.month===reportPaymentSelectedMonth && String(r.pay||'غير محدد').trim()===p}).reduce((s,r)=>s+parseNum(r.totalInc),0)),backgroundColor:colors[i%colors.length],borderRadius:8,barPercentage:.72,categoryPercentage:.7}));
  }else{
    const months=monthAgg(source,y);
    labels=months.map(m=>m.label);
    datasets=pays.map((p,i)=>({label:p,data:months.map(m=>source.filter(r=>(y==='all'?getYear(r)==m.year:true)&&normalizeMonth(r.month,r.date)===m.month&&String(r.pay||'غير محدد').trim()===p).reduce((s,r)=>s+parseNum(r.totalInc),0)),backgroundColor:colors[i%colors.length],borderRadius:8,barPercentage:.72,categoryPercentage:.7}));
  }
  chart('reportPaymentMonthly',{type:'bar',data:{labels,datasets},options:{...baseOpts(),layout:{padding:{top:36}},plugins:{...baseOpts().plugins,legend:{labels:{color:css('--muted'),font:{family:'Cairo',weight:'900'}}},petatoeLabels:{enabled:true,fullMoney:true,avoidOverlap:true,offset:14,font:'900 10px Cairo',strokeWidth:5}},scales:{x:{stacked:false,ticks:{color:css('--text'),font:{family:'Cairo',weight:'700'},maxRotation:0,minRotation:0},grid:{display:false}},y:{stacked:false,ticks:{color:css('--muted')},grid:{color:'rgba(148,163,184,.13)'}}}}});
}

