function smartQuarterAutoYears(data=records){
  const ys=years(data).filter(Boolean).sort((a,b)=>a-b);
  const compare=ys.length?ys[ys.length-1]:defaultYear(data);
  const base=ys.includes(compare-1)?compare-1:(ys.length>1?ys[ys.length-2]:compare-1);
  return {base,compare};
}
function smartQuarterYears(data=records){return getYearButtonList(data).filter(y=>y!=='all').map(Number).filter(Boolean).sort((a,b)=>b-a)}
function smartQuarterActiveYears(data=records){
  const auto=smartQuarterAutoYears(data);
  if(!smartQuarterCustomCompare){
    smartQuarterBaseYear=auto.base; smartQuarterCompareYear=auto.compare;
    return auto;
  }
  const available=smartQuarterYears(data);
  if(!available.includes(Number(smartQuarterCompareYear))) smartQuarterCompareYear=auto.compare;
  if(!available.includes(Number(smartQuarterBaseYear))) smartQuarterBaseYear=auto.base;
  return {base:Number(smartQuarterBaseYear),compare:Number(smartQuarterCompareYear)};
}
