function salesIntelMonthCompareValue(r){
  const gross=parseNum(r&&r.totalInc);
  let net=parseNum(r&&r.totalEx);
  let tax=parseNum(r&&r.tax);
  if(!net && gross) net=gross/1.15;
  if(!tax && gross) tax=gross-net;
  if(salesIntelMonthCompareMode==='net') return net;
  if(salesIntelMonthCompareMode==='tax') return tax;
  return gross;
}

