function smartQuarterSignKey(v){
  v=Number(v)||0;
  return v>0?'positive':(v<0?'negative':'neutral');
}
function smartQuarterSignClass(v){
  const k=smartQuarterSignKey(v);
  return k==='positive'?'smart-quarter-positive pet-q-positive':(k==='negative'?'smart-quarter-negative pet-q-negative':'smart-quarter-neutral pet-q-neutral');
}
function smartQuarterSignStyle(v){
  const k=smartQuarterSignKey(v);
  if(k==='positive') return 'color:#22c55e!important;font-weight:950!important;text-shadow:0 0 10px rgba(34,197,94,.30)!important;';
  if(k==='negative') return 'color:#ef4444!important;font-weight:950!important;text-shadow:0 0 10px rgba(239,68,68,.30)!important;';
  return 'color:#cbd5e1!important;font-weight:950!important;';
}
function smartQuarterSignedMoney(v){
  v=Number(v)||0;
  const val=fmt(Math.abs(v));
  const st=smartQuarterSignStyle(v);
  if(v>0) return '<span dir="ltr" style="'+st+'">+ SAR '+val+'</span>';
  if(v<0) return '<span dir="ltr" style="'+st+'">- SAR '+val+'</span>';
  return '<span dir="ltr" style="'+st+'">SAR '+fmt(0)+'</span>';
}
function smartQuarterSignedPct(v){
  v=Number(v)||0;
  const val=Math.abs(v).toFixed(2)+'%';
  const st=smartQuarterSignStyle(v);
  if(v>0) return '<span dir="ltr" style="'+st+'">+ '+val+'</span>';
  if(v<0) return '<span dir="ltr" style="'+st+'">- '+val+'</span>';
  return '<span dir="ltr" style="'+st+'">0.00%</span>';
}
function applySmartQuarterTableColors(){
  const tbl=document.getElementById('smartQuarterTable');
  if(!tbl) return;
  tbl.querySelectorAll('td[data-qsign]').forEach(function(td){
    const key=td.getAttribute('data-qsign');
    const st=key==='positive'?'color:#22c55e!important;font-weight:950!important;text-shadow:0 0 10px rgba(34,197,94,.30)!important;':(key==='negative'?'color:#ef4444!important;font-weight:950!important;text-shadow:0 0 10px rgba(239,68,68,.30)!important;':'color:#cbd5e1!important;font-weight:950!important;');
    td.style.cssText += ';'+st;
    td.querySelectorAll('span').forEach(function(sp){sp.style.cssText += ';'+st;});
  });
}

