  $('entryForm').innerHTML=`<div class="entry-common-grid">${entryCommonHtml()}</div>
  <div class="entry-items-card">
    <div class="entry-items-head"><b>🧾 أصناف الفاتورة</b><button type="button" class="btn btn-ghost" onclick="addEntryItemRow()">➕ إضافة صنف آخر</button></div>
    <div id="entryItemsWrap">${entryItemRowHtml(0,{qty:1})}</div>
    <div id="entryInvoiceTotals" class="entry-invoice-totals"></div>
  </div>`;
  $('e_invoice').value=getNextManualInvoiceNo();
  $('e_date').addEventListener('change',()=>{$('e_month').value=normalizeMonth('', $('e_date').value)});
