    ['van','date','month','invoice','client','pay'].forEach(f=>{if($('e_'+f))$('e_'+f).value=r[f]??''});
    ['item','qty','price','disc','tax','totalEx','totalInc'].forEach(f=>{const el=document.querySelector(`.entry-item-row [data-field="${f}"]`);if(el)el.value=r[f]??(f==='qty'?1:'')});
