function delRecord(id){try{if(typeof canDelete==='function'&&!canDelete()){toastSafe('الصلاحية الحالية لا تسمح بالحذف');return}}catch(e){window.PETATOEUtils&&window.PETATOEUtils.warnSilentCatch&&window.PETATOEUtils.warnSilentCatch("index.html",e);}var deleted=records.find(r=>String(r.id)===String(id));if(!confirm('حذف السجل؟'))return;records=records.filter(r=>r.id!==id);try{document.dispatchEvent(new CustomEvent('petatoe:record-deleted',{detail:{id:id,record:deleted}}))}catch(e){window.PETATOEUtils&&window.PETATOEUtils.warnSilentCatch&&window.PETATOEUtils.warnSilentCatch("index.html",e);}_invalidateSearchIndex();save();renderRecords()}function clearAll(){try{if(typeof canDelete==='function'&&!canDelete()){toastSafe('الصلاحية الحالية لا تسمح بحذف كل البيانات');return}}catch(e){window.PETATOEUtils&&window.PETATOEUtils.warnSilentCatch&&window.PETATOEUtils.warnSilentCatch("index.html",e);}if(!confirm('حذف كل البيانات؟'))return;records=[];try{document.dispatchEvent(new CustomEvent('petatoe:records-cleared'))}catch(e){window.PETATOEUtils&&window.PETATOEUtils.warnSilentCatch&&window.PETATOEUtils.warnSilentCatch("index.html",e);}_invalidateSearchIndex();save();renderRecords()}function renderRecords(){if(window.__PETATOE_RECORDS_SAFE_READY__&&typeof window.renderRecordsSafe==='function')return window.renderRecordsSafe();let q=($('recordSearch').value||'').toLowerCase(),ps=+$('pageSize').value||100,arr=records.filter(r=>!q||fields.some(f=>String(r[f]||'').toLowerCase().includes(q)));let pages=Math.max(1,Math.ceil(arr.length/ps));currentPage=Math.min(currentPage,pages);let slice=arr.slice((currentPage-1)*ps,currentPage*ps);$('recordsTable').innerHTML='<thead><tr><th>#</th>'+HEADERS.map(h=>`<th>${h}</th>`).join('')+'<th>إجراء</th></tr></thead><tbody>'+slice.map((r,i)=>`<tr><td>${(currentPage-1)*ps+i+1}</td>`+fields.map(f=>`<td>${f==='van'?`<span class="badge ${String(r[f]).includes('VAN A')||String(r[f]).includes('AXB')?'vana':'vanb'}">${htmlSafe(r[f]||'')}</span>`:f==='pay'?`<span class="badge ${r[f]==='نقدي'?'cash':'net'}">${htmlSafe(r[f]||'')}</span>`:htmlSafe(r[f]??'')}</td>`).join('')+`<td><button class="btn btn-ghost" onclick='fillForm(${JSON.stringify(r).replace(/'/g,"&#39;")})'>✏️</button> <button class="btn btn-danger" onclick="delRecord(${r.id})">🗑️</button></td></tr>`).join('')+'</tbody>';$('pagerInfo').textContent=`صفحة ${currentPage} من ${pages} | عرض ${slice.length} من ${arr.length} سجل`}function prevPage(){currentPage=Math.max(1,currentPage-1);renderRecords()}function nextPage(){currentPage++;renderRecords()}
