function smartHeatmapDefaultYear(){
  const ys=getYearButtonList(records).map(Number).filter(Boolean).sort((a,b)=>a-b);
  const currentYear=new Date().getFullYear();
  if(ys.includes(currentYear)) return String(currentYear);
  return String(ys[ys.length-1]||currentYear);
}
