function ensureHeatCalendarModal(){
  let ov=$('heatCalendarOverlay');
  if(ov)return ov;
  ov=document.createElement('div');
  ov.id='heatCalendarOverlay';
  ov.className='heat-calendar-overlay';
  ov.innerHTML='<div class="heat-calendar-modal" id="heatCalendarModal"></div>';
  ov.addEventListener('click',e=>{if(e.target===ov)closeHeatCalendar()});
  document.body.appendChild(ov);
  return ov;
}
function closeHeatCalendar(){const ov=$('heatCalendarOverlay');if(ov)ov.classList.remove('show')}
function showHeatMonthCalendar(activeYear,monthIndex){
  const y=String(activeYear);
  const monthName=MONTHS[monthIndex];
  const base=y==='all'?records.slice():records.filter(r=>String(getYear(r))===y);
  const activeVan=String(window.smartHeatmapVan||'').trim();
  const rows=smartDataCutoff(base,y).filter(r=>normalizeMonth(r.month,r.date)===monthName && (!activeVan || String(r.van||'').trim()===activeVan));
  const byDay={};
  rows.forEach(r=>{
    const iso=parseDate(r.date); if(!iso)return;
    const d=new Date(iso); if(isNaN(d))return;
    const day=y==='all'?d.getDate():d.getDate();
    if(!byDay[day])byDay[day]={sales:0,count:0};
    byDay[day].sales+=parseNum(r.totalInc); byDay[day].count+=1;
  });
  const vals=Object.entries(byDay).map(([day,o])=>({day:+day,sales:o.sales,count:o.count})).filter(x=>x.sales>0);
  const high=vals.length?vals.reduce((a,b)=>b.sales>a.sales?b:a,vals[0]):null;
  const low=vals.length?vals.reduce((a,b)=>b.sales<a.sales?b:a,vals[0]):null;
  const displayYear=y==='all'?defaultYear(records):+y;
  const daysInMonth=new Date(displayYear,monthIndex+1,0).getDate();
  const startDay=new Date(displayYear,monthIndex,1).getDay();
  const total=vals.reduce((s,x)=>s+x.sales,0);
  const invoices=rows.length;
  let cells='';
  for(let i=0;i<startDay;i++)cells+='<div class="heat-day-card empty"></div>';
  for(let d=1;d<=daysInMonth;d++){
    const o=byDay[d]||{sales:0,count:0};
    const isHigh=high&&d===high.day&&o.sales>0;
    const isLow=low&&d===low.day&&o.sales>0&&(!isHigh || vals.length===1);
    const cls=isHigh?' high':(isLow?' low':'');
    const badge=isHigh?'<span class="heat-day-badge high">أعلى مبيعات</span>':(isLow?'<span class="heat-day-badge low">أقل مبيعات</span>':'');
    cells+=`<div class="heat-day-card${cls}"><div><div class="heat-day-num">${d}</div>${badge}</div><div><div class="heat-day-sales">${o.sales?shortMoney(o.sales):'—'}</div><div class="heat-day-count">${o.count?fmt0(o.count)+' عملية':'لا توجد مبيعات'}</div></div></div>`;
  }
  const ov=ensureHeatCalendarModal();
  $('heatCalendarModal').innerHTML=`<div class="heat-calendar-head"><div><h3>📅 ${MAR[monthName]} ${y==='all'?'كل السنوات':y}</h3><p>تفاصيل المبيعات اليومية للشهر المحدد من Heatmap أيام الضغط</p></div><button class="heat-close-btn" onclick="closeHeatCalendar()">×</button></div>
  <div class="heat-calendar-kpis"><div class="heat-cal-kpi"><span>إجمالي الشهر</span><b>${money(total)}</b></div><div class="heat-cal-kpi"><span>عدد العمليات</span><b>${fmt0(invoices)}</b></div><div class="heat-cal-kpi"><span>أعلى يوم</span><b>${high?high.day+' - '+money(high.sales):'—'}</b></div><div class="heat-cal-kpi"><span>أقل يوم</span><b>${low?low.day+' - '+money(low.sales):'—'}</b></div></div>
  <div class="heat-calendar-weekdays"><div>الأحد</div><div>الإثنين</div><div>الثلاثاء</div><div>الأربعاء</div><div>الخميس</div><div>الجمعة</div><div>السبت</div></div><div class="heat-calendar-grid">${cells}</div><div class="heat-calendar-legend"><span><i class="heat-dot green"></i>أعلى يوم مبيعات</span><span><i class="heat-dot red"></i>أقل يوم مبيعات</span><span>القيم مختصرة داخل اليوم، والتفاصيل الكاملة في مؤشرات الأعلى</span></div>`;
  ov.classList.add('show');
}


