/* PETATOE v5.1.62 - Safe Smart Reports rerender helper
   Restores local filter buttons after Phase 3 by providing the missing helper used by report controls. */
function petatoeSmartReportsRows(){
  try{
    if(window.PETATOEDataSource && typeof window.PETATOEDataSource.getRecordsSync==='function'){
      const rows=window.PETATOEDataSource.getRecordsSync();
      return Array.isArray(rows)?rows:[];
    }
  }catch(e){}
  return Array.isArray(records)?records:[];
}
function petatoeSmartRerender(tab){
  const current=(document.querySelector('#smartTabs .smart-pill.active')||{}).dataset?.smartTab || 'overview';
  const target=tab || current;

  // PETATOE v6.4.148: Keep lazy-rendered Smart Vehicles filters local.
  // The previous v6.4.146 branch called records() although records is the global array here,
  // so the year chips threw an error and stayed stuck on the same year.
  if(target==='vehicles' && typeof renderSmartVans==='function'){
    renderSmartVans(petatoeSmartReportsRows());
    setSmartTab('vehicles');
    return;
  }

  if(target==='services' && typeof renderSmartServicesReport==='function'){ renderSmartServicesReport(); setSmartTab('services'); return; }
  renderSmartReports();
  setSmartTab(target);
}

function smartData(){
  try{
    if(window.PETATOESmartReportsData&&typeof window.PETATOESmartReportsData.getRows==='function'){
      const rows=window.PETATOESmartReportsData.getRows();
      if(Array.isArray(rows))return rows.slice();
    }
  }catch(_e){}
  return (records||[]).slice();
} // SR4: canonical Smart Reports data provider with legacy fallback
function smartDateValue(r){
  const ds=parseDate(r.date);
  if(!ds)return null;
  const d=new Date(ds+'T12:00:00');
  return isNaN(d)?null:d;
}
function maxInvoiceRecordForYear(source, year){
  const rows=source.filter(r=>String(getYear(r))===String(year)).filter(r=>smartDateValue(r));
  if(!rows.length)return null;
  return rows.slice().sort((a,b)=>{
    const ia=invoiceNumValue(a.invoice), ib=invoiceNumValue(b.invoice);
    if(ia!==ib)return ib-ia;
    return smartDateValue(b)-smartDateValue(a);
  })[0];
}
function maxInvoiceDateForYear(source, year){
  // PETATOE v5.1.8 DATA CUTOFF FIX
  // The previous implementation selected the latest invoice by invoice serial first.
  // That can incorrectly stop 2025 at September when a September invoice has a higher serial than Oct/Nov/Dec.
  // For report availability, heatmaps, and year cutoffs, the source of truth must be the maximum invoice DATE.
  const dates=(source||[])
    .filter(r=>String(getYear(r))===String(year))
    .map(r=>smartDateValue(r))
    .filter(Boolean)
    .sort((a,b)=>b-a);
  return dates[0]||null;
}
function smartDataCutoff(source, year){
  if(String(year)==='all')return (source||[]).slice();
  const yearRows=(source||[]).filter(r=>String(getYear(r))===String(year));
  const maxDate=maxInvoiceDateForYear(yearRows, year);
  if(!maxDate)return yearRows;
  const start=makeLocalDate(year,1,1);
  const end=makeLocalDate(year,maxDate.getMonth()+1,maxDate.getDate());
  end.setHours(23,59,59,999);
  return yearRows.filter(r=>{const d=smartDateValue(r);return d && d>=start && d<=end;});
}

window.PETATOEYearDataAudit=function(year,source){
  const src=source||records||[];
  const rows=src.filter(r=>String(getYear(r))===String(year));
  const months={};
  rows.forEach(r=>{const d=smartDateValue(r); if(!d)return; const k=String(d.getMonth()+1).padStart(2,'0'); months[k]=(months[k]||0)+1;});
  return {year:String(year),rows:rows.length,maxDate:maxInvoiceDateForYear(src,year),months:months};
};

