// === PETATOE v2.6 AI Forecast helpers - add-only, no change to old reports ===
function petatoeLinearForecast(points, months){
  if(!points.length) return months.map(()=>0);
  const n=points.length;
  const sx=points.reduce((s,p)=>s+p.x,0), sy=points.reduce((s,p)=>s+p.y,0);
  const sxx=points.reduce((s,p)=>s+p.x*p.x,0), sxy=points.reduce((s,p)=>s+p.x*p.y,0);
  const den=(n*sxx-sx*sx)||1;
  const b=(n*sxy-sx*sy)/den;
  const a=(sy-b*sx)/n;
  return months.map(x=>Math.max(0,a+b*x));
}
function petatoeMovingAvgForecast(values, months, windowSize){
  const last=values.slice(-windowSize);
  const avg=safeDiv(last.reduce((s,x)=>s+x,0),last.length||1);
  return months.map(()=>Math.max(0,avg));
}
function petatoeMape(actual,pred){
  let total=0,c=0;
  actual.forEach((a,i)=>{ if(a>0){ total+=Math.abs(a-(pred[i]||0))/a; c++; }});
  return c?total/c:0.35;
}
function buildPetatoeAIForecast(monthly,data,lastActual){
  const actual=monthly.filter(x=>x.idx<=lastActual && x.sales>0);
  const values=actual.map(x=>x.sales);
  const points=actual.map(x=>({x:x.idx,y:x.sales}));
  const months=monthly.map(x=>x.idx);
  const futureMonths=monthly.filter(x=>x.idx>lastActual).map(x=>x.idx);
  const avg=safeDiv(values.reduce((s,x)=>s+x,0),values.length||1);
  if(!actual.length){
    return {forecastFull:monthly.map(()=>0),next:0,quarter:0,yearEnd:0,confidence:0,best:'No Data',riskIndex:0,models:[],explain:'لا توجد بيانات كافية لبناء توقع موثوق.',serviceRisk:[],serviceGrowth:[],customerRisk:[]};
  }
  const fullTrend=petatoeLinearForecast(points,months);
  const ma3=petatoeMovingAvgForecast(values,months,3);
  const ma6=petatoeMovingAvgForecast(values,months,6);
  const seasonal=monthly.map(x=>{
    const prev=monthly.find(m=>m.idx===x.idx-12);
    return prev&&prev.sales?prev.sales:avg;
  });
  function backtest(modelName){
    if(actual.length<4) return 0.22;
    const train=actual.slice(0,-1);
    const test=actual.slice(-1);
    const trainVals=train.map(x=>x.sales);
    let pred;
    if(modelName==='Trend') pred=petatoeLinearForecast(train.map(x=>({x:x.idx,y:x.sales})),test.map(x=>x.idx));
    else if(modelName==='Moving Avg 3') pred=petatoeMovingAvgForecast(trainVals,test.map(x=>x.idx),3);
    else if(modelName==='Moving Avg 6') pred=petatoeMovingAvgForecast(trainVals,test.map(x=>x.idx),6);
    else pred=[safeDiv(trainVals.reduce((s,x)=>s+x,0),trainVals.length||1)];
    return petatoeMape(test.map(x=>x.sales),pred);
  }
  const models=[
    {name:'Trend',desc:'يراقب اتجاه الصعود أو الهبوط خلال الشهور الفعلية.',data:fullTrend,error:backtest('Trend')},
    {name:'Moving Avg 3',desc:'يعتمد على متوسط آخر 3 شهور فعلية لتقليل الضوضاء.',data:ma3,error:backtest('Moving Avg 3')},
    {name:'Moving Avg 6',desc:'يعتمد على متوسط أطول وأكثر هدوءًا عند تذبذب البيانات.',data:ma6,error:backtest('Moving Avg 6')}
  ].sort((a,b)=>a.error-b.error);
  const best=models[0];
  const confidence=Math.max(45,Math.min(95,Math.round((1-best.error)*100)));
  const blended=monthly.map((x,i)=>{
    if(x.idx<=lastActual) return x.sales;
    const v=(best.data[i]*0.62)+(ma3[i]*0.23)+(fullTrend[i]*0.15);
    return Math.max(0,v);
  });
  const nextIdx=Math.min(11,lastActual+1);
  const next=lastActual>=11?monthly[lastActual].sales:(blended[nextIdx]||0);
  const quarter=futureMonths.slice(0,3).reduce((s,idx)=>s+(blended[idx]||0),0);
  const yearEnd=actual.reduce((s,x)=>s+x.sales,0)+futureMonths.reduce((s,idx)=>s+(blended[idx]||0),0);
  const recent=safeDiv(values.slice(-3).reduce((s,x)=>s+x,0),Math.min(values.length,3)||1);
  const previous=safeDiv(values.slice(-6,-3).reduce((s,x)=>s+x,0),Math.min(Math.max(values.length-3,0),3)||1);
  const riskIndex=Math.round(Math.max(0,Math.min(100,50+(previous?((previous-recent)/previous)*80:0)+(100-confidence)*0.35)));
  const itemMonths={};
  data.forEach(r=>{const item=(r.item||'غير محدد').trim();const m=normalizeMonth(r.month,r.date);const idx=MONTHS.indexOf(m);if(idx<0)return;itemMonths[item]=itemMonths[item]||Array(12).fill(0);itemMonths[item][idx]+=parseNum(r.totalInc);});
  const serviceRows=Object.entries(itemMonths).map(([name,arr])=>{
    const oldAvg=safeDiv(arr.slice(Math.max(0,lastActual-5),Math.max(0,lastActual-2)).reduce((s,x)=>s+x,0),3);
    const recentAvg=safeDiv(arr.slice(Math.max(0,lastActual-2),lastActual+1).reduce((s,x)=>s+x,0),3);
    const change=oldAvg?safeDiv(recentAvg-oldAvg,oldAvg)*100:(recentAvg>0?100:0);
    return {name,oldAvg,recentAvg,change,total:arr.reduce((s,x)=>s+x,0)};
  }).filter(x=>x.total>0);
  const serviceRisk=serviceRows.filter(x=>x.change<-25).sort((a,b)=>a.change-b.change).slice(0,5);
  const serviceGrowth=serviceRows.filter(x=>x.change>25).sort((a,b)=>b.change-a.change).slice(0,5);
  const now=data.map(r=>smartDateValue(r)).filter(Boolean).sort((a,b)=>b-a)[0]||new Date();
  const custMap={};
  data.forEach(r=>{const c=(r.client||'غير محدد').trim();const d=smartDateValue(r);custMap[c]=custMap[c]||{name:c,total:0,count:0,last:null};custMap[c].total+=parseNum(r.totalInc);custMap[c].count++;if(d && (!custMap[c].last || d>custMap[c].last))custMap[c].last=d;});
  const customerRisk=Object.values(custMap).map(c=>({name:c.name,total:c.total,count:c.count,last:c.last,days:c.last?Math.floor((now-c.last)/(24*60*60*1000)):999})).filter(c=>c.total>0 && c.days>=45).sort((a,b)=>(b.total*b.days)-(a.total*a.days)).slice(0,7);
  let explain='تم اختيار نموذج '+best.name+' لأنه أقل خطأ في الاختبار الخلفي داخل البيانات الحالية.';
  if(recent>previous && previous>0) explain+=' الاتجاه الأخير صاعد مقارنة بالفترة السابقة.';
  else if(recent<previous && previous>0) explain+=' الاتجاه الأخير هابط مقارنة بالفترة السابقة، لذلك تم رفع درجة الحذر.';
  else explain+=' البيانات الحالية مستقرة نسبيًا.';
  return {forecastFull:blended,next,quarter,yearEnd,confidence,best:best.name,riskIndex,models,explain,serviceRisk,serviceGrowth,customerRisk};
}
function petatoeUpdateWhatIf(){
  const st=window.petatoeAIForecastState;if(!st)return;
  const s=+$('whatIfSales')?.value||0, c=+$('whatIfCustomers')?.value||0, a=+$('whatIfAvg')?.value||0;
  if($('whatIfSalesVal'))$('whatIfSalesVal').textContent=s+'%';
  if($('whatIfCustomersVal'))$('whatIfCustomersVal').textContent=c+'%';
  if($('whatIfAvgVal'))$('whatIfAvgVal').textContent=a+'%';
  const factor=(1+s/100)*(1+c/100)*(1+a/100);
  const v=st.next*factor;
  if($('aiWhatIfResult'))$('aiWhatIfResult').innerHTML=`التوقع المعدل للشهر القادم: <b>${money(v)}</b> — الفرق عن التوقع الأساسي: <b>${money(v-st.next)}</b>`;
}


/* PETATOE v6.2.3 Phase 2: Smart Reports core moved to smart/smart-reports-core.js?v=9.4.20-translation-stability */
